// Lattice Fusion - reactor output simulation (Mark 1 demonstration run)
// Run with: node demo.js
'use strict';
var out=[12,480,20000], eff=[38,72,96];
console.log("Lattice Fusion - power output by generation");
console.log("==================================================");
for(var m=0;m<3;m++){
  var homes=Math.round(out[m]*1000/1.2); // ~1.2 kW per home
  console.log("Mark "+(m+1)+": "+out[m]+" MW at "+eff[m]+"% efficiency -> ~"+homes.toLocaleString()+" homes");
}
console.log("Ramp profile: 0-100% in "+[45,12,3].map(function(x,i){return "Mark "+(i+1)+": "+x+" min";}).join(", "));

